H.background();
// Inclined plane:  a = g(sin θ − μ cos θ)   along the ramp (down-slope positive).
// Gravity mg splits into a component mg·sinθ down the slope and mg·cosθ into it
// (which sets N). Friction μN opposes sliding. If mg sinθ ≤ μ mg cosθ the block
// stays put; otherwise it accelerates down at a = g(sinθ − μcosθ) and resets.
const g = 9.8;
const m = Math.max(0.1, P.m);
const deg = Math.max(1, Math.min(P.deg, 80));
const mu = Math.max(0, P.mu);
const th = deg * Math.PI / 180;
const W = m * g;
const along = W * Math.sin(th);     // mg sinθ  (drives it down)
const into = W * Math.cos(th);      // mg cosθ  (sets normal)
const N = into;
const fMax = mu * N;
const net = along - fMax;           // net once it slides (kinetic-style)
const slides = net > 0;
const a = slides ? net / m : 0;     // a = g(sinθ − μcosθ) only if it overcomes friction
// friction drawn: kinetic μN if sliding, else exactly cancels mg sinθ (static)
const fric = slides ? fMax : Math.min(fMax, along);
const v = H.plot2d({ xMin: -1, xMax: 11, yMin: -1, yMax: 8, box: { x: 50, y: 70, w: H.W - 100, h: H.H - 150 } });
const x0 = 0.5, y0 = 0.5;                  // bottom-left of ramp
const L = 9.5;                             // ramp base length
const rx = x0 + L, ry = y0 + L * Math.tan(th); // top corner
v.path([[x0, y0], [rx, y0], [rx, ry], [x0, y0]], { color: H.colors.axis, width: 2, fill: H.colors.panel, close: true });
const ux = Math.cos(th), uy = Math.sin(th); // unit vector up the slope
const sMax = L / Math.cos(th);              // slope length (hypotenuse)
// Motion: if it slides, real kinematics s = ½ a τ² from the top until it reaches
// the bottom, then reset (looping). If static, the block sits parked partway up.
let sPos;
if (slides) {
  const tFall = Math.sqrt(2 * sMax / a);    // time to slide the full ramp
  const tau = t % tFall;                    // loop each fall
  sPos = sMax - 0.5 * a * tau * tau;        // start at top, accelerate down
  sPos = Math.max(0, Math.min(sMax, sPos));
} else {
  sPos = sMax * 0.55;                       // stays put on the ramp
}
const bx = x0 + sPos * ux, by = y0 + sPos * uy;
const bw = 0.9;
const nx = -Math.sin(th), ny = Math.cos(th); // unit normal to slope
const corner = (sx, sy) => [bx + sx * ux + sy * nx, by + sx * uy + sy * ny];
v.path([corner(-bw / 2, 0), corner(bw / 2, 0), corner(bw / 2, bw), corner(-bw / 2, bw)], { color: H.colors.accent, width: 2, fill: H.colors.bg, close: true });
const ccx = bx + bw / 2 * nx, ccy = by + bw / 2 * ny; // block center
v.text("m", ccx, ccy, { color: H.colors.ink, size: 12, align: "center" });
const SF = 2.2 / Math.max(W, 1e-6);
v.arrow(ccx, ccy, ccx, ccy - W * SF, { color: H.colors.warn, width: 3 });                              // weight (down)
v.arrow(ccx, ccy, ccx - along * SF * ux, ccy - along * SF * uy, { color: H.colors.accent, width: 3 }); // along (down-slope)
v.arrow(ccx, ccy, ccx + N * SF * nx, ccy + N * SF * ny, { color: H.colors.violet, width: 3 });         // normal
v.arrow(ccx, ccy, ccx + fric * SF * ux, ccy + fric * SF * uy, { color: H.colors.good, width: 3 });     // friction up-slope
H.text("Inclined plane:  a = g(sin θ − μ cos θ)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("θ = " + deg.toFixed(0) + "°    mg sinθ = " + along.toFixed(1) + " N    N = mg cosθ = " + N.toFixed(1) + " N    f_max = " + fMax.toFixed(1) + " N", 24, 52, { color: H.colors.sub, size: 12 });
H.text(slides ? "slides:  a = " + a.toFixed(2) + " m/s² down the slope" : "static:  mg sinθ ≤ μ mg cosθ → stays put", 24, H.H - 26, { color: slides ? H.colors.good : H.colors.warn, size: 14, weight: 700 });
H.legend([{ label: "weight mg", color: H.colors.warn }, { label: "mg sinθ", color: H.colors.accent }, { label: "normal N", color: H.colors.violet }, { label: "friction f", color: H.colors.good }], H.W - 150, 28);
